class Solution {
public:
    int subsequenceCount(vector<int>& nums) {
        const long long MOD = 1e9 + 7;
        bool hasOdd = false;
        for (int x : nums) if (x & 1) hasOdd = true;
        if (!hasOdd) return 0;
        long long r = 1, b = 2, e = nums.size() - 1;
        while (e) {
            if (e & 1) r = r * b % MOD;
            b = b * b % MOD;
            e >>= 1;
        }
        return (int)r;
    }
};

