class Solution {
    public int subsequenceCount(int[] nums) {
        final long MOD = 1_000_000_007L;
        boolean hasOdd = false;
        for (int x : nums) if ((x & 1) == 1) hasOdd = true;
        if (!hasOdd) return 0;
        long r = 1, b = 2, e = nums.length - 1;
        while (e > 0) {
            if ((e & 1) == 1) r = r * b % MOD;
            b = b * b % MOD;
            e >>= 1;
        }
        return (int)r;
    }
}

