var subsequenceCount = function(nums) {
    const MOD = 1e9 + 7;
    if (!nums.some(x => x % 2 !== 0)) return 0;
    let r = 1, b = 2, e = nums.length - 1;
    while (e > 0) {
        if (e & 1) r = r * b % MOD;
        b = b * b % MOD;
        e = Math.floor(e / 2);
