        MOD = 10**9 + 7
        even, odd = 1, 0
        for x in nums:
            if x % 2:
                even, odd = (even + odd) % MOD, (even + odd) % MOD
            else:
                even, odd = even * 2 % MOD, odd * 2 % MOD
        return odd

